import pytest

from english_draughts import initial_position, perft

# Reference perft values for English checkers from the standard start position.
EXPECTED = {1: 7, 2: 49, 3: 302, 4: 1469, 5: 7361, 6: 36768}


@pytest.mark.parametrize("depth", sorted(EXPECTED))
def test_perft(depth):
    assert perft(initial_position(), depth) == EXPECTED[depth]


def test_perft_all():
    pos = initial_position()
    for depth, expected in EXPECTED.items():
        assert perft(pos, depth) == expected, f"perft({depth})"

